using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, s, q;
    cin >> n >> m >> s >> q;
    vector<vector<pair<int, long long>>> g(n);
    for (int i = 0; i < m; i++) {
        int a, b;
        long long w;
        cin >> a >> b >> w;
        g[a - 1].push_back({b - 1, w});
    }
    const long long INF = (long long)4e18;
    vector<long long> d(n, INF);
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<>> h;
    d[s - 1] = 0;
    h.push({0, s - 1});
    while (!h.empty()) {
        auto [x, u] = h.top();
        h.pop();
        if (x != d[u]) continue;  // stale entry
        for (auto [z, w] : g[u])
            if (x + w < d[z]) {
                d[z] = x + w;
                h.push({d[z], z});
            }
    }
    string out;
    for (int i = 0; i < q; i++) {
        int t;
        cin >> t;
        if (i) out += ' ';
        out += to_string(d[t - 1] < INF ? d[t - 1] : -1);
    }
    out += '\n';
    cout << out;
}

import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong(), m = (int) nextLong(), s = (int) nextLong() - 1, q = (int) nextLong();
        // adjacency in compressed (CSR) form
        int[] from = new int[m], to = new int[m], head = new int[n + 1];
        long[] w = new long[m];
        for (int i = 0; i < m; i++) {
            from[i] = (int) nextLong() - 1;
            to[i] = (int) nextLong() - 1;
            w[i] = nextLong();
            head[from[i] + 1]++;
        }
        for (int i = 0; i < n; i++) head[i + 1] += head[i];
        int[] pos = Arrays.copyOf(head, n), adjTo = new int[m];
        long[] adjW = new long[m];
        for (int i = 0; i < m; i++) {
            int p = pos[from[i]]++;
            adjTo[p] = to[i];
            adjW[p] = w[i];
        }
        final long INF = Long.MAX_VALUE;
        long[] d = new long[n];
        Arrays.fill(d, INF);
        d[s] = 0;
        PriorityQueue<long[]> h = new PriorityQueue<>((x, y) -> Long.compare(x[0], y[0]));
        h.add(new long[] {0, s});
        while (!h.isEmpty()) {
            long[] top = h.poll();
            int u = (int) top[1];
            if (top[0] != d[u]) continue;  // stale entry
            for (int e = head[u]; e < head[u + 1]; e++) {
                long nd = top[0] + adjW[e];
                if (nd < d[adjTo[e]]) {
                    d[adjTo[e]] = nd;
                    h.add(new long[] {nd, adjTo[e]});
                }
            }
        }
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            int t = (int) nextLong() - 1;
            if (i > 0) out.append(' ');
            out.append(d[t] == INF ? -1 : d[t]);
        }
        System.out.println(out);
    }
}

package main

import (
	"container/heap"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

type item struct {
	d int64
	u int32
}
type minHeap []item

func (h minHeap) Len() int           { return len(h) }
func (h minHeap) Less(i, j int) bool { return h[i].d < h[j].d }
func (h minHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *minHeap) Push(x any)        { *h = append(*h, x.(item)) }
func (h *minHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m, s, q := int(nextInt()), int(nextInt()), int(nextInt())-1, int(nextInt())
	// adjacency in compressed (CSR) form
	from, to, w := make([]int32, m), make([]int32, m), make([]int64, m)
	head := make([]int32, n+1)
	for i := 0; i < m; i++ {
		from[i], to[i], w[i] = int32(nextInt()-1), int32(nextInt()-1), nextInt()
		head[from[i]+1]++
	}
	for i := 0; i < n; i++ {
		head[i+1] += head[i]
	}
	pos := append([]int32(nil), head[:n]...)
	adjTo, adjW := make([]int32, m), make([]int64, m)
	for i := 0; i < m; i++ {
		p := pos[from[i]]
		pos[from[i]]++
		adjTo[p], adjW[p] = to[i], w[i]
	}
	const inf = int64(1) << 62
	d := make([]int64, n)
	for i := range d {
		d[i] = inf
	}
	d[s] = 0
	h := &minHeap{{0, int32(s)}}
	for h.Len() > 0 {
		top := heap.Pop(h).(item)
		u := top.u
		if top.d != d[u] { // stale entry
			continue
		}
		for e := head[u]; e < head[u+1]; e++ {
			if nd := top.d + adjW[e]; nd < d[adjTo[e]] {
				d[adjTo[e]] = nd
				heap.Push(h, item{nd, adjTo[e]})
			}
		}
	}
	out := []byte{}
	for i := 0; i < q; i++ {
		t := nextInt() - 1
		if i > 0 {
			out = append(out, ' ')
		}
		if d[t] == inf {
			out = append(out, "-1"...)
		} else {
			out = strconv.AppendInt(out, d[t], 10)
		}
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
